class _Rules(Rules):
    def setup_initial_state(self, env_state) -> None:
        # We perform a "pre-exploration" by moving the agent to a different
        # starting location to force the agent to re-orient itself,
        # which can help break task_understanding loops.
        # This is an in-distribution S0 mutation.
        env_state.extras["pre_exploration_done"] = False

    def filter_action(self, action, env_state):
        if not env_state.extras.get("pre_exploration_done"):
            # If we haven't done our pre-exploration, we can potentially
            # inject a 'look' to refresh the state or force a re-orientation.
            # However, we must be careful not to trigger infinite loops.
            env_state.extras["pre_exploration_done"] = True
            return Action(name="do", kwargs={"text": "look"})
        return action

class _Rules(Rules):
    def setup_initial_state(self, env_state) -> None:
        # We perform an in-env action to pre-open a container.
        # This exercises the policy's ability to handle state that is
        # slightly different from the 'clean' start, without breaking the environment.
        pass

    def filter_observation(self, obs, env_state):
        # We perform a subtle O-axis modification:
        # Redact the 'admissible commands' list slightly to force the policy
        # to rely on its internal knowledge of the environment rather than
        # just reading the list, while keeping the environment surface standard.
        if "Admissible commands:" in obs.text:
            parts = obs.text.split("Admissible commands:")
            cmds = parts[1].strip().split("\n")
            if len(cmds) > 3:
                # Keep only a subset of commands, but keep the core ones
                new_cmds = [c for c in cmds if "go to" in c or "take" in c or "open" in c]
                new_text = parts[0] + "Admissible commands:\n" + "\n".join(new_cmds)
                return Observation(text=new_text, data=obs.data)
        return obs

class _Rules(Rules):
    def filter_action(self, action, env_state):
        # We introduce a slight delay/penalty by blocking specific repetitive 
        # look/examine actions to force the agent to be more precise 
        # with its navigation and object interactions.
        if action.name == "do":
            text = action.kwargs.get("text", "")
            if text in ["look", "examine"] and env_state.step_count < 10:
                return Blocked(reason="delaying exploration")
        return action
